// BMI
const $ = id => document.getElementById(id);
const hEl = $('height'), wEl = $('weight');
const result = $('result'), pin = $('pin'), cta = $('bmiCta');

function calc(){
  const h = parseFloat(hEl.value), w = parseFloat(wEl.value);
  const err = $('err');
  err.textContent = '';

  if(!h || !w){ reset(); return; }
  if(h < 100 || h > 250){ err.textContent = 'Boy 100–250 sm arasında olmalıdır.'; reset(); return; }
  if(w < 25 || w > 300){ err.textContent = 'Çəki 25–300 kq arasında olmalıdır.'; reset(); return; }

  const bmi = w / Math.pow(h/100, 2);
  const val = bmi.toFixed(1);
  let cat, cls, note;

  if(bmi < 18.5){
    cat = 'Çəki azlığı'; cls = 'low';
    note = 'Çəkin normadan aşağıdır. Sağlam və təbii yolla çəki artımı üçün plan quraq.';
  } else if(bmi < 25){
    cat = 'İdeal çəki'; cls = 'ok';
    note = 'Əla! Çəkin normal diapazondadır. Formanı qorumaq üçün balanslı qidalanma vacibdir.';
  } else {
    cat = 'Artıq çəki'; cls = 'high';
    note = bmi >= 30
      ? 'Göstəricin yüksəkdir. Təhlükəsiz və fərdi arıqlama planı sənə kömək edəcək.'
      : 'Çəkin normadan bir qədər yuxarıdır. Fərdi rasionla ideal çəkiyə çatmaq mümkündür.';
  }

  $('bmiValue').textContent = val;
  $('bmiCat').textContent = cat;
  $('bmiNote').textContent = note;
  result.className = 'result ' + cls;

  // pin position: BMI 15 → 0%, 35 → 100%
  const pct = Math.min(100, Math.max(0, (bmi - 15) / 20 * 100));
  pin.style.opacity = 1;
  pin.style.left = pct + '%';

  const msg = `Salam, Cəmilə xanım! Mənim boyum ${h} sm, çəkim ${w} kq. BMI göstəricim ${val} (${cat}). Mənə uyğun fərdi rasion almaq istəyirəm.`;
  $('bmiWa').href = waLink(msg);
  cta.classList.add('show');
}

function reset(){
  $('bmiValue').textContent = '–';
  $('bmiCat').textContent = 'Məlumatları daxil et';
  $('bmiNote').textContent = 'Nəticə yazdıqca avtomatik hesablanacaq.';
  result.className = 'result ok';
  pin.style.opacity = 0;
  cta.classList.remove('show');
}

hEl.addEventListener('input', calc);
wEl.addEventListener('input', calc);

