const STEP = 8;
const grid = $('gallery'), moreBtn = $('moreBtn');
let filter = 'all', shown = STEP, current = [], lbIndex = 0;

// Şəkil formatı jpg, jpeg, png və ya webp ola bilər — avtomatik yoxlanılır
const EXTS = ['jpg','jpeg','png','webp','JPG','JPEG','PNG'];
const baseOf = r => `images/${r.file || r.f}`;
const srcOf = r => r.img || `${baseOf(r)}.jpg`;
function setSrc(img, base){
  img.dataset.base = base;
  img.dataset.try = 0;
  img.src = `${base}.${EXTS[0]}`;
}
function nextExt(img){
  if(!img.dataset.base) return false;
  const n = (+img.dataset.try || 0) + 1;
  if(n < EXTS.length){ img.dataset.try = n; img.src = `${img.dataset.base}.${EXTS[n]}`; return true; }
  return false;
}
const ZOOM_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l4.5 4.5M11 8.5v5M8.5 11h5"/></svg>';

function renderGallery(){
  current = RESULTS.filter(r => filter === 'all' || r.cat === filter);
  grid.innerHTML = current.slice(0, shown).map((r, i) => {
    const src = srcOf(r);
    const cls = r.up ? 'up' : r.cat === 'sac' ? 'hair' : r.cat === 'uz' ? 'skin' : '';
    return `
    <button class="rcard" data-i="${i}" style="animation-delay:${(i % STEP) * 60}ms" aria-label="${CATS[r.cat]} nəticəsi">
      <div class="shot">
        <img class="bg" ${r.img ? '' : `data-base="${baseOf(r)}"`} src="${src}" alt="" loading="lazy" aria-hidden="true">
        <img class="fg" ${r.img ? '' : `data-base="${baseOf(r)}"`} src="${src}" alt="${CATS[r.cat]} nəticəsi" loading="lazy">
      </div>
      <div class="rinfo">
        <div><span class="rcat ${r.cat}">${CATS[r.cat]}</span><div class="rres ${cls}">${r.res}</div></div>
        <div class="rnote">${r.note}</div>
      </div>
    </button>`;
  }).join('');
  moreBtn.parentElement.style.display = current.length > shown ? 'flex' : 'none';
}

// şəkil tapılmasa gözəl placeholder
grid.addEventListener('error', e => {
  const img = e.target;
  if(img.tagName !== 'IMG') return;
  if(!nextExt(img)) img.closest('.shot')?.classList.add('empty');
}, true);

grid.addEventListener('click', e => {
  const card = e.target.closest('.rcard');
  if(card) openLb(+card.dataset.i);
});

moreBtn.addEventListener('click', () => { shown += STEP; renderGallery(); });

$('filters').addEventListener('click', e => {
  const b = e.target.closest('.fbtn'); if(!b) return;
  document.querySelectorAll('.fbtn').forEach(x => x.classList.remove('active'));
  b.classList.add('active');
  filter = b.dataset.f; shown = STEP; renderGallery();
});

// Lightbox
const lb = $('lb'), lbImg = $('lbImg'), lbCap = $('lbCap');
function showLb(){
  const r = current[lbIndex];
  if(r.img){ lbImg.removeAttribute('data-base'); lbImg.src = r.img; }
  else setSrc(lbImg, baseOf(r));
  lbCap.innerHTML = `<b>${r.res}</b>${CATS[r.cat]} · ${r.note}`;
}
function openLb(i){ lb.classList.remove('single'); lbIndex = i; showLb(); lb.classList.add('open'); document.body.style.overflow = 'hidden'; }
function openSingle(src, cap){
  lb.classList.add('single'); lbImg.removeAttribute('data-base'); lbImg.src = src; lbCap.innerHTML = cap;
  lb.classList.add('open'); document.body.style.overflow = 'hidden';
}
function closeLb(){ lb.classList.remove('open'); document.body.style.overflow = ''; }
function stepLb(d){ if(lb.classList.contains('single')) return; lbIndex = (lbIndex + d + current.length) % current.length; showLb(); }

lbImg.addEventListener('error', () => nextExt(lbImg));
$('lbClose').addEventListener('click', closeLb);
$('lbPrev').addEventListener('click', e => { e.stopPropagation(); stepLb(-1); });
$('lbNext').addEventListener('click', e => { e.stopPropagation(); stepLb(1); });
lb.addEventListener('click', e => { if(e.target === lb) closeLb(); });
document.addEventListener('keydown', e => {
  if(!lb.classList.contains('open')) return;
  if(e.key === 'Escape') closeLb();
  if(e.key === 'ArrowLeft') stepLb(-1);
  if(e.key === 'ArrowRight') stepLb(1);
});
let tx = 0;
lb.addEventListener('touchstart', e => { tx = e.touches[0].clientX; }, {passive:true});
lb.addEventListener('touchend', e => {
  const dx = e.changedTouches[0].clientX - tx;
  if(Math.abs(dx) > 50) stepLb(dx < 0 ? 1 : -1);
});

