// Şəkli olmayan kateqoriyaların filtr düymələrini gizlət
const usedCats = new Set(RESULTS.map(r => r.cat));
document.querySelectorAll('.fbtn').forEach(b => {
  if(b.dataset.f !== 'all' && !usedCats.has(b.dataset.f)) b.style.display = 'none';
});
if(usedCats.size < 2) $('filters').style.display = 'none';

renderGallery();

// Scroll reveal
const io = new IntersectionObserver((entries) => {
  entries.forEach(e => { if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
}, { threshold: .12 });
document.querySelectorAll('.reveal').forEach((el, i) => {
  el.style.transitionDelay = (i % 4) * 70 + 'ms';
  io.observe(el);
});